const items = $input.all();

return items.map(item => {
  // 1. Get the AI response
  let rawText = item.json.text || "";

  // 2. Remove Markdown code fences if present
  rawText = rawText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // 3. Parse the JSON response
  const recipe = JSON.parse(rawText);

  // 4. Format ingredients, including nested objects
  function formatIngredients(ingredients) {
    return Object.entries(ingredients || {})
      .map(([key, value]) => {
        const name = key
          .replace(/_/g, " ")
          .replace(/\b\w/g, char => char.toUpperCase());

        if (value && typeof value === "object" && !Array.isArray(value)) {
          return `\n*${name}:*\n${formatIngredients(value)}`;
        }

        return `• ${name}: ${value}`;
      })
      .join("\n");
  }

  // 5. Safely get instructions and cooking tips
  const instructions = Array.isArray(recipe.instructions)
    ? recipe.instructions
    : [];

  const tips = Array.isArray(recipe.cooking_tips)
    ? recipe.cooking_tips
    : [];

  // 6. Create the Slack message
  const message = [
    `🍝 *${recipe.recipe_name || "Recipe"}*`,
    "",
    `⏱️ *Preparation Time:* ${recipe.preparation_time || "N/A"}`,
    `🔥 *Cooking Time:* ${recipe.cooking_time || "N/A"}`,
    `🍽️ *Servings:* ${recipe.servings ?? "N/A"}`,
    "",
    "🛒 *INGREDIENTS*",
    formatIngredients(recipe.ingredients) || "No ingredients provided",
    "",
    "👨‍🍳 *INSTRUCTIONS*",
    ...(instructions.length
      ? instructions.map((step, index) => `${index + 1}. ${step}`)
      : ["No instructions provided"]),
    "",
    "💡 *COOKING TIPS*",
    ...(tips.length
      ? tips.map(tip => `• ${tip}`)
      : ["No cooking tips provided"])
  ].join("\n");

  // 7. Return output for the Slack node
  return {
    json: {
      recipe_name: recipe.recipe_name || "Recipe",
      slack_message: message
    }
  };
});
